;; Luigi's training stage (0.4.37, src/game/tutorial/heroes/luigi.ts; docs/HEROES.md): only what
;; is different from Mario. He starts in a well (cols 1-4) whose tall side only his higher jump
;; clears (cols 5-8), then the run (the sprint bar: gate at 31), the slide onto the hard-block strip before a
;; shallow ditch (gate at 42), the wide ditch to a higher far bank that only his floatier running
;; jump clears (its far wall is too tall to climb from inside), an optional ? block (a mushroom) and
;; the flagpole. The gates are laid by the tutorial.
id: training-luigi
name: LUIGI TRAINING
world: 1
stage: 0
theme: overworld
music: overworld
time: 400
start: 1,13
startMode: stand
camera: scroll

[tiles]
;; 0                16               32               48               64               80
